import { mkdir, unlink, writeFile } from "node:fs/promises";
import path from "node:path";

/**
 * FILE STORAGE ADAPTER
 * ====================
 * Every upload goes through this interface so the storage backend can change
 * without touching a single call site. Today it writes to `.storage/` inside the
 * project; in production the same three functions would talk to S3, R2 or
 * UploadThing.
 *
 * SECURITY RULES ENFORCED HERE
 * ---------------------------
 * 1. Keys are GENERATED by the server (uuid + known extension) and never taken
 *    from user input, so `../../etc/passwd` is unrepresentable.
 * 2. The resolved path is re-checked to be inside the storage root. This is a
 *    belt-and-braces guard: even a bug that let a separator through cannot write
 *    outside the directory.
 * 3. The key is normalised to forward slashes before it becomes a path, so it
 *    behaves identically on Windows and Linux.
 */

const STORAGE_ROOT = path.join(process.cwd(), ".storage");

/** Absolute path for a storage key, with a containment check. */
export function resolveStoragePath(storageKey: string): string {
  const normalised = path
    .normalize(storageKey)
    .replace(/\\/g, "/")
    .replace(/^(\.\.(\/|$))+/, "");

  const absolute = path.resolve(STORAGE_ROOT, normalised);
  const rootWithSep = STORAGE_ROOT.endsWith(path.sep) ? STORAGE_ROOT : STORAGE_ROOT + path.sep;

  if (!absolute.startsWith(rootWithSep)) {
    throw new Error("Refusing to write outside the storage directory.");
  }
  return absolute;
}

export async function saveFile(storageKey: string, bytes: Buffer): Promise<void> {
  const absolute = resolveStoragePath(storageKey);
  await mkdir(path.dirname(absolute), { recursive: true });
  await writeFile(absolute, bytes);
}

export async function deleteFile(storageKey: string): Promise<void> {
  const absolute = resolveStoragePath(storageKey);
  await unlink(absolute);
}

/** Public URL served by the file route. */
export function publicUrlFor(storageKey: string): string {
  return `/files/${storageKey.replace(/\\/g, "/")}`;
}
